-- 212 — اصلاح نص قرار الهيئة 236/2024 (نموذج النظام الأساسى لصناديق التأمين الخاصة) كاملاً: 59 مادة، من نسخة الوقائع المصرية (العدد 257 تابع (ب) فى 19 نوفمبر 2024)
-- ----------------------------------------------------------------------------
-- المشكلة: النص المخزَّن من استخراج PDF فيه (1) أقواس مقلوبة ومبعثرة فى نحو 70 موضعاً، وأخطرها خانات الملء الفارغة: "( )(%....." فى المادة 59 بدل "(.....%)"،
--          و") :شهرى /ربع سنوى /... سنوي(" فى المادة 8 بدل "(شهرى / ربع سنوى / نصف سنوى / سنوى)"، (2) عناوين الأبواب مدسوسة فى آخر المادة السابقة،
--          (3) علامات التنوين والضمة محذوفة (اعتبارا/يعمل بدل اعتبارًا/يُعمل) لأنها كانت أحرف خاصة غير مقروءة.
-- الإصلاح: أُعيد بناء النص من أحرف الملف نفسه بإحداثياتها، ثم قورن بالنص المخزَّن مادةً مادة: الحروف العربية والأرقام مطابقة تماماً فى كل المواد الـ59
--          (الفرق: الأقواس وعلامات الترقيم والتنوين والفقرات والعناوين فقط). المادة 8 والمادة 59 رُوجعتا بصرياً على صور الصفحات.
--          عناوين الأبواب حُذفت من متون المواد ووُضعت فى عمود hierarchical_location للمواد (حين يكون فارغاً فقط).
-- الضمان: كل مادة تُحدَّث فقط إذا كان md5 نصها الحالى أحد النصين المقيسين (قبل/بعد 208) أو كانت "بصمتها الحرفية" (الحروف والأرقام بعد حذف
--          ا أ إ آ ل ه والعلامات) مطابقة لبصمة النص المتوقع؛ غير ذلك: تحذير وتخطٍّ دون كتابة. النص القديم يُحفظ فى migration_212_backup.
--          نسخ article_versions المطابقة تُحدَّث معها. embeddings لا تُمس. قابلة لإعادة التشغيل.
-- ============================================================================

CREATE TABLE IF NOT EXISTS migration_212_backup (
  article_id uuid NOT NULL,
  version_id uuid,
  old_body   text NOT NULL,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_212_backup_art ON migration_212_backup (article_id) WHERE version_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_212_backup_ver ON migration_212_backup (version_id) WHERE version_id IS NOT NULL;

