    (3, ARRAY['c2d6f7c3a06351269dc4dabbe28c6908','f6c02cab37236efce2caae7a6d2ae38d']::text[], ARRAY['fbf5331c6d1a9b78905fa3f20f8bac82']::text[], 'e42b20e8193edc74a9427f5f77b1931f', 'الباب الثانى - إنشاء الصندوق', replace($b$تصدر الهيئة قرار إنشاء الصندوق واعتماد نظامه الأساسى وقيده لدى الهيئة ، ولا يجوز للصندوق مزاولة نشاطه إلا بعد تمام القيد فى سجل الهيئة ويُعد ذلك ترخيصًا بمزاولة النشاط ، ويكتسب الصندوق الشخصية الاعتبارية الخاصة بمجرد القيد ، وبعد سداد رسوم القيد المقررة .
وينشر قرار القيد والنظام الأساسى على الموقع الإلكترونى للصندوق وكذا الموقع الإلكترونى الذى تخصصه الهيئة لهذا الغرض مع مراعاة أحكام المادة (67) من قانون التأمين الموحد .$b$, E'\n', E'\r\n')),
